// Potentia core in JavaScript: a line-by-line port of potentia.py (pure bioelectric, finite non-periodic tissue).
// Same equations, constants, grid conventions and update order as the Python class; the only numerical difference is that
// the field convolution is a direct sum over the (sparse) kernel instead of an FFT, so results agree to round-off.
// Checked against reference states generated by the Python model: see core_test.js / make_js_reference.py.
(function (root) {
  'use strict';
  const K = { Z: 3, V_th: -27e-3, V_T: 27e-3, V_0: 12e-3, C: 0.1e-9, E_pol: -55e-3, E_dep: -5e-3, G_ref: 1.0e-9,
              a: 5.0e-6, k_e: 8.987e9, eps_r: 1e7, dt: 0.01, epsilon: 1e-15 };

  class PotentiaCore {
    // o: {sizeCells:[n0,n1], m, params:{fieldScreenSize, fieldStrength, gain, weight, bias, tau, GJStrength, fieldVector, leak|null, G_dep}, nSub}
    constructor(o) {
      const p = o.params;
      this.m = Math.round(o.m);
      this.sizeCells = o.sizeCells.slice();
      this.Rs = +p.fieldScreenSize; this.fs = +p.fieldStrength; this.gain = +p.gain; this.weight = +p.weight;
      this.bias = +p.bias; this.tau = +p.tau; this.GJ = +p.GJStrength; this.vector = !!p.fieldVector;
      this.leak = (p.leak === null || p.leak === undefined) ? K.G_ref : +p.leak;       // null = as implemented in the repo (1e-9)
      this.Gdep = (p.G_dep === undefined) ? 1.5 : +p.G_dep;
      this.pitch = 2 * K.a; this.h = this.pitch / this.m;
      this.Np0 = Math.round(this.sizeCells[0] * this.m); this.Np1 = Math.round(this.sizeCells[1] * this.m);
      this.R = K.a * Math.SQRT2 * (this.Rs + 0.001);
      this.nSub = this.m === 1 ? 1 : (o.nSub || 8);                                    // 'point' source for m=1, area-integrated otherwise
      if (this.nSub > 1 && this.nSub % 2) throw new Error('nSub must be even');
      this.fc = this.fs * (K.k_e / K.eps_r);
      this.half = (this.m % 2 === 1);
      const m = this.m;
      this.dk0 = this.half ? (1 - m) / 2 : -m / 2;                                      // perception probe offsets (index units)
      this.gjCoef = this.GJ * (K.G_ref / K.C) * m * m;
      this.kIon = K.G_ref / K.C;
      this.dt = (o.dt !== undefined && o.dt !== null) ? o.dt : (this.gjCoef > 0 ? Math.min(K.dt, 0.2 / this.gjCoef) : K.dt);
      this.L0 = this.Np0 + m; this.L1 = this.Np1 + m;                                   // probe grid (all probes any pixel perceives)
      this._buildKernel();
      this.E = new Float64Array(this.L0 * this.L1);
      this.ebar = new Float64Array(this.Np0 * this.Np1);
      this.dVgj = new Float64Array(this.Np0 * this.Np1);
    }

    _buildKernel() {
      const h = this.h, nS = this.nSub, R = this.R;
      const W = Math.ceil(R / h) + 3;
      const u = new Float64Array(nS);
      for (let k = 0; k < nS; k++) u[k] = nS > 1 ? ((k + 0.5) / nS - 0.5) * h : 0;
      const scale = this.fc * K.C * (h * h) / (this.pitch * this.pitch);               // charge per pixel = C V h^2/p^2
      const nx = [], ny = [], kx = [], ky = [];
      const cnt = nS * nS;
      for (let ix = -W; ix <= W; ix++) {
        const ox = this.half ? ix - 0.5 : ix;
        for (let iy = -W; iy <= W; iy++) {
          const oy = this.half ? iy - 0.5 : iy;
          let sx = 0, sy = 0;
          for (let a = 0; a < nS; a++) {
            const dX = ox * h - u[a];
            for (let b = 0; b < nS; b++) {
              const dY = oy * h - u[b], r2 = dX * dX + dY * dY;
              if (Math.sqrt(r2) <= R) {
                if (this.vector) { sx += dX / r2; sy += dY / r2; } else { sx += 1 / Math.sqrt(r2); }
              }
            }
          }
          const a0 = sx / cnt * scale, a1 = sy / cnt * scale;
          if (a0 !== 0 || a1 !== 0) { nx.push(ix); ny.push(iy); kx.push(a0); ky.push(a1); }
        }
      }
      this.nEntries = nx.length;
      this.entNx = Int32Array.from(nx); this.entNy = Int32Array.from(ny);
      this.entKx = Float64Array.from(kx); this.entKy = Float64Array.from(ky);
    }

    info() {
      return { Np: [this.Np0, this.Np1], size_cells: this.sizeCells.slice(), m: this.m, dt: this.dt, h_um: this.h * 1e6, R_um: this.R * 1e6,
               tissue_um: [this.Np0 * this.h * 1e6, this.Np1 * this.h * 1e6], kernel_px: this.R / this.h, entries: this.nEntries,
               work_per_step: this.L0 * this.L1 * this.nEntries * (this.vector ? 2 : 1) };
    }

    // |E| (vector) or scalar potential on the probe grid: E[k] = sum_s K[k - s] V[s]  (zero outside the tissue)
    _field(V) {
      const { Np0, Np1, L0, L1, dk0, nEntries, entNx, entNy, entKx, entKy, E, vector } = this;
      const eps = K.epsilon;
      for (let pi = 0; pi < L0; pi++) {
        const kxp = pi + dk0;
        for (let pj = 0; pj < L1; pj++) {
          const kyp = pj + dk0;
          let ex = 0, ey = 0;
          for (let e = 0; e < nEntries; e++) {
            const sx = kxp - entNx[e]; if (sx < 0 || sx >= Np0) continue;
            const sy = kyp - entNy[e]; if (sy < 0 || sy >= Np1) continue;
            const v = V[sx * Np1 + sy];
            ex += entKx[e] * v; ey += entKy[e] * v;
          }
          E[pi * L1 + pj] = vector ? Math.sqrt(ex * ex + ey * ey + eps) : ex;
        }
      }
    }

    _perceive() {                                                                      // mean of the 4 corner probes of every pixel
      const { Np0, Np1, L1, m, E, ebar } = this;
      for (let i = 0; i < Np0; i++) for (let j = 0; j < Np1; j++)
        ebar[i * Np1 + j] = 0.25 * (E[i * L1 + j] + E[i * L1 + j + m] + E[(i + m) * L1 + j] + E[(i + m) * L1 + j + m]);
    }

    _gj(V) {                                                                           // gated diffusion, no-flux edges
      const { Np0, Np1, m, gjCoef, dVgj } = this, V0 = K.V_0;
      dVgj.fill(0);
      for (let i = 0; i < Np0; i++) for (let j = 0; j < Np1; j++) {
        const k = i * Np1 + j;
        if (i + 1 < Np0) { const d = V[k + Np1] - V[k], f = gjCoef * d * (2.0 / (1.0 + Math.cosh(m * d / V0))); dVgj[k] += f; dVgj[k + Np1] -= f; }
        if (j + 1 < Np1) { const d = V[k + 1] - V[k], f = gjCoef * d * (2.0 / (1.0 + Math.cosh(m * d / V0))); dVgj[k] += f; dVgj[k + 1] -= f; }
      }
    }

    // one step, in place on V (volts) and g (G_pol/G_ref); same order as potentia.py: field -> g -> V
    step(V, g) {
      this._field(V); this._perceive();
      const { Np0, Np1, ebar, gain, bias, weight, tau, leak, dt, kIon, Gdep, dVgj } = this;
      const n = Np0 * Np1, r10 = 10.0 / tau;
      for (let k = 0; k < n; k++) {
        const x = gain * ebar[k] + bias;
        const dg = r10 * (-leak * g[k] + weight * Math.tanh(0.5 * x));
        let gn = g[k] + dt * dg; g[k] = gn < 0 ? 0 : gn > 2 ? 2 : gn;
      }
      this._gj(V);
      for (let k = 0; k < n; k++) {
        const v = V[k], ein = Math.exp(K.Z * (v - K.V_th) / K.V_T), Pin = 1.0 / (1.0 + ein), Pout = ein / (1.0 + ein);
        const ion = kIon * (-g[k] * (v - K.E_pol) * Pin - Gdep * (v - K.E_dep) * Pout);
        V[k] = v + dt * (ion + dVgj[k]);
      }
    }

    // sensed field / bias for display (does not change the state)
    perceivedOverBias(V) {
      this._field(V); this._perceive();
      const out = new Float64Array(this.ebar.length);
      for (let k = 0; k < out.length; k++) out[k] = this.ebar[k] / this.bias;
      return out;
    }
  }

  const api = { PotentiaCore, K };
  if (typeof module !== 'undefined' && module.exports) module.exports = api; else root.PotentiaCoreLib = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);
